    padding: 2rem 0.75rem;
    text-align: center;
  }

  .ml-table-empty-content {
    display: inline-block;
  }

  .ml-text-muted {
    color: var(--ml-on-surface-muted, #49454f);
  }

  // ====================================================================
  // LOADING STATE — skeleton placeholders
  // ====================================================================
  .ml-table-loading {
    width: 100%;
    background: var(--ml-surface, #ffffff);
    border-radius: var(--ml-radius-sm, 6px);
  }

  .ml-skeleton {
    background: linear-gradient(
      90deg,
      var(--ml-surface-dim, #f5f5f5) 25%,
      var(--ml-surface-variant, #ede8f5) 50%,
      var(--ml-surface-dim, #f5f5f5) 75%
    );
    background-size: 200% 100%;
    border-radius: var(--ml-radius-sm, 6px);
    animation: ml-skeleton-shimmer 1.4s ease-in-out infinite;
  }

  @keyframes ml-skeleton-shimmer {
    0%   { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }

  // ====================================================================
  // PAGINATION
  // ====================================================================
  .ml-table-pagination {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.25rem;
    padding-top: 0.5rem;
    color: var(--ml-on-surface-muted, #49454f);
  }

  .ml-table-page-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.75rem;
    height: 1.75rem;
    padding: 0 0.375rem;
    font-size: 0.75rem;
    font-family: var(--ml-font-family, system-ui, -apple-system, sans-serif);
    color: var(--ml-on-surface-muted, #49454f);
    background: transparent;
    border: var(--ml-border-width, 1px) var(--ml-border-style, solid) transparent;
    border-radius: var(--ml-radius-sm, 6px);
    cursor: pointer;
    transition: background var(--ml-transition, 200ms ease),
                border-color var(--ml-transition, 200ms ease),
                color var(--ml-transition, 200ms ease);

    &:hover:not(:disabled) {
      background: var(--ml-surface-dim, #f5f5f5);
      border-color: var(--ml-outline-variant, #e2e8f0);
      color: var(--ml-on-surface, #1c1b1f);
    }

    &:focus-visible {
      outline: var(--ml-focus-ring-width, 2px) solid var(--ml-focus-ring-color, rgba(59,130,246,0.4));
      outline-offset: 1px;
    }

    &:disabled {
      opacity: var(--ml-disabled-opacity, 0.5);
      cursor: not-allowed;
    }
  }

  // Active page button
  .ml-table-page-btn-active {
    background: var(--ml-primary, #3b82f6) !important;
    color: var(--ml-on-primary, #ffffff) !important;
    border-color: var(--ml-primary, #3b82f6) !important;
    font-weight: var(--ml-font-weight-medium, 500);
    cursor: default;
  }

  // ====================================================================
  // ERROR TEXT
  // ====================================================================
  .ml-error-text {
    color: var(--ml-error, #ef4444);
    font-size: 0.75rem;
    margin-top: 0.25rem;
    display: block;
  }
}
